import {DISPLAY_LIMIT,MAX_OPS} from './engine.mjs';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const tr=(lang,fr,en)=>lang==='en'?en:fr;
const ext=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} <span aria-hidden="true">↗</span><span class="sr-only"> (new tab / nouvel onglet)</span></a>`;
export function summary(result,lang){const t=(fr,en)=>tr(lang,fr,en);if(result.status==='unknown')return t('URL absente du corpus : aucun calcul possible.','URL absent from the corpus: calculation unavailable.');if(result.status==='unreachable')return t('Aucun chemin trouvé dans ce périmètre. Cela ne prouve ni l’absence de liens réels ni une page orpheline.','No path found within this scope. This proves neither the absence of real links nor an orphan page.');return t(`Dans cette archive, cette destination est atteignable depuis ce départ en suivant au minimum ${result.distance} lien${result.distance===1?'':'s'}. ${result.count} chemin${result.count==='1'?'':'s'} ${result.count==='1'?'minimal':'minimaux'} ${result.count==='1'?'est disponible':'sont disponibles'}.`,`In this archive, this destination can be reached from this starting URL by following at least ${result.distance} link${result.distance===1?'':'s'}. ${result.count} shortest path${result.count==='1'?' is':'s are'} available.`);}
export function resultCard(result,lang,label){const t=(fr,en)=>tr(lang,fr,en);return `<article class="metric-card"><h3>${esc(label)}</h3><div class="metrics"><div><strong>${result.distance??'—'}</strong><span>${t('liens au minimum','minimum links')}</span></div><div><strong>${result.count}</strong><span>${t('chemins minimaux','shortest paths')}</span></div></div><p>${esc(summary(result,lang))}</p>${!result.target_outgoing_documented?`<p class="warning">${t('Destination : liens sortants non documentés.','Destination: outgoing links are not documented.')}</p>`:''}${!result.source_outgoing_documented?`<p class="warning">${t('Départ : liens sortants non documentés ; le calcul ne peut pas poursuivre depuis cette URL.','Start: outgoing links are undocumented; the calculation cannot continue from this URL.')}</p>`:''}</article>`;}
export function pathMarkup(path,display,lang,operations=[]){const t=(fr,en)=>tr(lang,fr,en);if(!path)return `<p>${t('Aucun chemin à représenter.','No path to display.')}</p>`;return `<ol class="path">${path.map((url,i)=>{const r=display.records[url];const simulated=i>0&&operations.some(o=>o.type==='add'&&o.from===path[i-1]&&o.to===url);return `<li><span class="step">${i===0?t('DÉPART','START'):t('ÉTAPE','STEP')+' '+i}</span><strong>${esc(r?.label??url)}</strong><small>${r?.label_basis==='observed_h1'?t('H1 archivé','Archived H1'):t('Libellé dérivé de l’URL','URL-derived label')}${r?.kind==='resource'?t(' · ressource',' · resource'):''}</small><span class="url">${esc(url)}</span>${i>0?`<a class="proof-link" href="#relation-${i}">${simulated?t('Relation simulée · voir la preuve','Simulated relation · inspect evidence'):t('Relation archivée · voir la preuve','Archived relation · inspect evidence')}</a>`:`<a href="#node-proof">${t('Examiner cette URL','Inspect this URL')}</a>`}</li>`;}).join('')}</ol>`;}
export function evidenceMarkup(path,display,lang,operations=[],graph){const t=(fr,en)=>tr(lang,fr,en);if(!path)return `<p>${t('Choisissez un chemin pour examiner ses relations.','Choose a path to inspect its relations.')}</p>`;
 const node=(url)=>{const r=display.records[url],m=r?.metadata;return `<div class="node-meta"><h4>${esc(r?.label??url)}</h4><p class="url">${esc(url)}</p><p>${r?.source_documented?t('Source : adjacency documentée.','Source: documented adjacency.'):t('Destination connue ; liens sortants non documentés.','Known destination; undocumented outgoing links.')}</p>${m?`<dl><dt>H1</dt><dd>${esc(m.h1)}</dd><dt>${t('Langue archivée','Archived language')}</dt><dd>${esc(m.lang)}</dd><dt>Canonical</dt><dd class="url">${esc(m.canonical)}</dd><dt>HTTP / robots</dt><dd>${esc(m.status)} / ${esc(m.robots)}</dd></dl><a href="originals/pages.csv">pages.csv · ${t('ligne','line')} ${m.row}</a>`:`<p>${t('Intitulé dérivé de l’URL ; H1, titre, statut HTTP, canonical et robots non documentés pour cette URL dans pages.csv.','URL-derived label; H1, title, HTTP status, canonical and robots are not documented for this URL in pages.csv.')}</p>`}<p>${ext(url,t('Ouvrir l’URL actuelle','Open the current URL'))}</p></div>`;};
 return `<details id="node-proof"><summary>${t('URL de départ : métadonnées et périmètre','Starting URL: metadata and scope')}</summary>${node(path[0])}</details>`+path.slice(1).map((to,i)=>{const from=path[i],op=operations.find(o=>o.type==='add'&&o.from===from&&o.to===to);const link=display.link_metadata.find(r=>r.source_url===from&&r.destination_url===to);const idx=graph?.get(from)?.indexOf(to);return `<details id="relation-${i+1}"><summary><span>${String(i+1).padStart(2,'0')}</span> ${op?t('Modification simulée','Simulated change'):t('Relation archivée','Archived relation')} · ${esc(display.records[to]?.label??to)}</summary><div class="evidence-body"><p class="tag">${op?t('HYPOTHÈSE · ajout par le scénario','HYPOTHESIS · added by this scenario'):t('ARCHIVE · 9 SEPTEMBRE 2026','ARCHIVE · 9 SEPTEMBER 2026')}</p><dl><dt>${t('Source','Source')}</dt><dd class="url">${esc(from)}</dd><dt>${t('Destination','Destination')}</dt><dd class="url">${esc(to)}</dd><dt>${t('Référence','Reference')}</dt><dd>${op?`scenario.operations[${operations.indexOf(op)}]`: `<a href="originals/graph.json">graph.json</a> → adjacency[<span class="url">${esc(JSON.stringify(from))}</span>][${idx??'?'}]`}</dd></dl><pre>${esc(JSON.stringify(op??{source:from,destination:to,observed_at:display.provenance.observed_at},null,2))}</pre><p>${t('Ancre : non renseignée. Emplacement dans la page : inconnu. Aucun classement menu/contenu/footer n’est déduit.','Anchor text: unavailable. Page area: unknown. No menu/content/footer classification is inferred.')}</p>${link?`<p>${t('Extrait documentaire complémentaire','Additional documentary extract')} : <a href="originals/links.csv">links.csv · ${t('ligne','line')} ${link.row}</a> ; ${esc(link.occurrence_count)} ${t('occurrence(s) enregistrée(s). La relation est dédupliquée dans le calcul.','recorded occurrence(s). The relation is deduplicated in the calculation.')}</p>`:`<p>${t('Pas de ligne supplémentaire dans l’extrait links.csv ; la preuve de relation est dans graph.json.','No additional row in the links.csv excerpt; relation evidence is in graph.json.')}</p>`}<details><summary>${t('Métadonnées des deux URL','Metadata for both URLs')}</summary>${node(from)}${node(to)}</details></div></details>`;}).join('');
}
export function quickResult(result,display,lang){const t=(fr,en)=>tr(lang,fr,en);return `<small>${t('GRAPHE ARCHIVÉ','ARCHIVED GRAPH')} · ${display.provenance.observed_at}</small><div class="quick-metrics"><strong>${result.distance??'—'}</strong><span>${t('liens au minimum','minimum links')}</span><strong>${result.count}</strong><span>${t('chemins minimaux','shortest paths')}</span></div><p>${esc(display.records[result.root]?.label??result.root)}<span aria-hidden="true"> → </span>${esc(display.records[result.target]?.label??result.target)}</p><a href="#path-view">${t('Voir un chemin et ses alternatives','View a path and its alternatives')} ↓</a>`;}
export function page(display,graph,lang){const t=(fr,en)=>tr(lang,fr,en),initial=display.references[0],s=display.statistics;return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${t('Maillage interne : quels chemins mènent à vos pages clés ?','Internal linking: which paths lead to your key pages?')} — Edikka</title><meta name="description" content="${t('Explorez un graphe Edikka archivé, vérifiez ses chemins et simulez des relations. Calcul exact et reproductible, sans promesse SEO.','Explore an archived Edikka graph, verify its paths and simulate relations. Exact, reproducible calculations with no SEO claims.')}"><link rel="canonical" href="https://edikkaweb.github.io/seo-architecture-demo/${lang==='en'?'index-en.html':''}"><link rel="alternate" hreflang="fr" href="https://edikkaweb.github.io/seo-architecture-demo/"><link rel="alternate" hreflang="en" href="https://edikkaweb.github.io/seo-architecture-demo/index-en.html"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script type="module" src="assets/app.mjs"></script></head><body><a class="skip" href="#explore">${t('Aller au calcul','Skip to calculation')}</a><header class="wrap header"><a class="brand" href="https://www.edikka.com/">edikka<span>.</span></a><span class="lab-label">${t('INSTRUMENTS<br>OUVERTS','OPEN<br>INSTRUMENTS')}</span><nav aria-label="${t('Navigation principale','Main navigation')}"><a href="#method">${t('Méthode & limites','Method & limits')}</a><a id="language" href="${lang==='en'?'index.html':'index-en.html'}" hreflang="${lang==='en'?'fr':'en'}" lang="${lang==='en'?'fr':'en'}">${lang==='en'?'FR':'EN'} <span aria-hidden="true">↗</span></a></nav></header><main class="wrap"><section class="hero"><p class="eyebrow">${t('ARCHITECTURE SEO · EXPLORATION D’UNE ARCHIVE','SEO ARCHITECTURE · EXPLORING AN ARCHIVE')}</p><h1>${t('Maillage interne.<br><span>Quels chemins mènent<br>à vos pages clés ?</span>','Internal linking.<br><span>Which paths lead<br>to your key pages?</span>')}</h1><p class="lead">${t('Suivre un chemin. Vérifier chaque lien. Tester une hypothèse.','Follow a path. Verify each link. Test a hypothesis.')}</p><p class="hero-note">${t('Des relations documentées, pas une prédiction de classement. Aucun crawl n’est lancé pendant votre visite.','Documented relations, not a ranking prediction. No crawl runs during your visit.')}</p><div class="scope-chip" id="quick-result">${quickResult(initial,display,lang)}</div></section><nav class="action-nav" aria-label="${t('Parcours de la démonstration','Demo journey')}"><a href="#explore"><span>01</span> ${t('Explorer les chemins','Explore paths')}</a><a href="#simulate"><span>02</span> ${t('Simuler une modification','Simulate a change')}</a><a href="#evidence"><span>03</span> ${t('Examiner les preuves','Examine evidence')}</a></nav><p id="load-note" class="muted">${t('L’exemple archivé est lisible ci-dessous. Chargement des commandes interactives…','The archived example is readable below. Loading interactive controls…')}</p><noscript><p class="notice">${t('JavaScript est désactivé : les exemples calculés, leurs preuves et la procédure de reproduction restent disponibles. L’exploration et la simulation nécessitent JavaScript.','JavaScript is disabled: calculated examples, evidence and reproduction instructions remain available. Exploration and simulation require JavaScript.')}</p></noscript><div id="scenario-error" class="notice" hidden><p id="scenario-error-text"></p><button id="recover">${t('Revenir à l’exemple initial','Return to the initial example')}</button></div><section id="explore" class="section"><div class="section-heading"><div><p class="eyebrow">01 / ${t('EXPLORER','EXPLORE')}</p><h2>${t('D’un point à un autre.','From one point to another.')}</h2></div><p>${t('Graphe archivé le','Graph archived on')} <strong>${display.provenance.observed_at}</strong><br>${t('Paquet','Package')} ${display.provenance.data_version} · ${t('Démo','Demo')} ${display.demo_version}</p></div><form id="explore-form"><fieldset id="explore-controls" disabled><legend class="sr-only">${t('Choisir les URL du calcul','Choose calculation URLs')}</legend><div class="selector-grid">${['from','to'].map((id,i)=>`<div class="picker"><label for="${id}-search">${i===0?t('Rechercher le départ','Search starting URL'):t('Rechercher la destination','Search destination')}</label><input id="${id}-search" type="search" placeholder="URL / ${t('intitulé','label')}" aria-describedby="picker-help"><label class="small-label" for="${id}">${i===0?t('Départ sélectionné','Selected start'):t('Destination sélectionnée','Selected destination')}</label><select id="${id}"></select></div>`).join('')}<button class="primary" type="submit">${t('Explorer les chemins','Explore paths')} →</button></div><p id="picker-help" class="small">${t('Recherche par URL ou intitulé. La sélection reste visible même si elle ne correspond pas au filtre. Les groupes distinguent sources documentées et destinations seules.','Search URL or label. The selection remains visible even when it does not match the filter. Groups distinguish documented sources from destination-only URLs.')}</p></fieldset></form><p id="calculation-scope" class="small">${t('Calcul depuis la racine publiée du manifeste.','Calculation from the root published in the manifest.')}</p><div id="comparison" class="comparison">${resultCard(initial,lang,t('Plus court chemin dans le graphe archivé','Shortest path in the archived graph'))}</div><p id="effect" class="notice" hidden></p><p class="small">${t('La longueur décrit ce graphe uniquement : ni score SEO, ni indexation, ni trafic, ni probabilité de visite. Aucune règle universelle de trois clics.','Length describes this graph only: no SEO score, indexation, traffic or visit probability. No universal three-click rule.')}</p><div class="path-toolbar"><h3>${t('Un chemin, étape par étape.','One path, step by step.')}</h3><div id="path-controls" hidden><label for="path-model">${t('Modèle','Model')}</label> <select id="path-model"><option value="archive">${t('Archive','Archive')}</option><option value="simulation">${t('Simulation','Simulation')}</option></select> <label for="path-choice">${t('Chemin','Path')}</label> <select id="path-choice"></select></div></div><p id="path-limit" class="small">${t('Ordre déterministe ; affichage borné à','Deterministic order; display limited to')} ${DISPLAY_LIMIT} ${t('chemins. Le total reste exact.','paths. The total remains exact.')}</p><div id="path-view">${pathMarkup(initial.paths[0],display,lang)}</div><p class="small">${t('Cette liste ordonnée constitue aussi le schéma : chaque étape suit une relation dirigée vers la suivante. Les URL complètes restent visibles.','This ordered list also forms the diagram: each step follows a directed relation to the next. Full URLs remain visible.')}</p></section><section id="simulate" class="section simulation"><div class="section-heading"><div><p class="eyebrow">02 / ${t('SIMULER','SIMULATE')}</p><h2>${t('Et si ce lien changeait ?','What if this link changed?')}</h2></div><span class="tag">${t('COPIE LOCALE DU GRAPHE','LOCAL COPY OF THE GRAPH')}</span></div><p>${t('Une hypothèse réversible, sans modification du site ni de l’archive. Huit opérations au maximum ; sources modifiables limitées aux adjacences documentées.','A reversible hypothesis, without changing the site or archive. Up to eight operations; editable sources are limited to documented adjacencies.')}</p><fieldset id="simulation-controls" disabled><legend class="sr-only">${t('Modifier le scénario','Edit the scenario')}</legend><div class="guided"><div><h3>${t('Deux hypothèses à essayer','Two hypotheses to try')}</h3><p>${t('Ces exemples remplacent le scénario par accueil → guide français.','These examples replace the scenario with home → French guide.')}</p></div><button id="guided-add" type="button">${t('Ajouter un lien direct','Add a direct link')} ↗</button><button id="guided-remove" type="button">${t('Retirer le lien depuis la FAQ','Remove the FAQ link')} −</button></div><form id="operation-form"><div class="selector-grid">${['op-from','op-to'].map((id,i)=>`<div class="picker"><label for="${id}-search">${i===0?t('Filtrer les sources modifiables','Filter editable sources'):t('Filtrer les destinations connues','Filter known destinations')}</label><input id="${id}-search" type="search" placeholder="URL / ${t('intitulé','label')}"><label class="small-label" for="${id}">${i===0?t('Source de la relation','Relation source'):t('Destination de la relation','Relation destination')}</label><select id="${id}"></select></div>`).join('')}<div class="operation-buttons"><label for="operation-type">${t('Opération','Operation')}</label><select id="operation-type"><option value="add">${t('Ajouter','Add')} →</option><option value="remove">${t('Retirer','Remove')} →</option></select><button type="submit" class="primary">${t('Appliquer l’hypothèse','Apply hypothesis')}</button></div></div></form><p id="operation-error" role="status" class="warning"></p><ol id="operations" class="operations"></ol><div class="button-row"><button id="undo" type="button">${t('Annuler la dernière modification','Undo last change')}</button><button id="reset" type="button">${t('Revenir au graphe archivé','Restore the archived graph')}</button></div></fieldset><p class="small">${t('Retirer une relation supprime le couple source–destination entier du modèle, pas nécessairement une occurrence HTML. Un raccourci calculé n’est pas une recommandation : la pertinence dépend du contenu et du besoin du lecteur.','Removing a relation deletes the entire source–destination pair from the model, not necessarily one HTML occurrence. A calculated shortcut is not a recommendation: relevance depends on the content and the reader’s needs.')}</p></section><section id="evidence" class="section"><p class="eyebrow">03 / ${t('EXAMINER','EXAMINE')}</p><h2>${t('La preuve, lien par lien.','Evidence, link by link.')}</h2><p>${t('Relations du chemin affiché. Ouvrir une URL actuelle ne reproduit pas l’observation du 9 septembre.','Relations in the displayed path. Opening a current URL does not reproduce the 9 September observation.')}</p><div id="evidence-view">${evidenceMarkup(initial.paths[0],display,lang,[],graph)}</div></section><section id="share" class="section"><h2>${t('Partager une hypothèse précise.','Share a precise hypothesis.')}</h2><p>${t('Le lien restaure la version des données, les deux URL et les opérations. Il ne contient aucune donnée de navigation personnelle.','The link restores the data version, both URLs and operations. It contains no personal browsing data.')}</p><div class="button-row"><button id="share-button" disabled>${t('Créer le lien partageable','Create a share link')}</button><button id="export-button" disabled>${t('Exporter le scénario JSON','Export scenario JSON')}</button></div><div id="export-output" hidden><label for="export-json">${t('JSON du scénario (copie possible si le téléchargement est bloqué)','Scenario JSON (copy if the download is blocked)')}</label><textarea id="export-json" rows="12" readonly></textarea><a id="export-download" download="edikka-architecture-scenario.json">${t('Télécharger le JSON','Download JSON')}</a></div><div id="share-output" hidden><label for="share-url">${t('Lien à copier','Link to copy')}</label><input id="share-url" readonly><a id="share-open" href="#">${t('Ouvrir ce scénario','Open this scenario')}</a></div></section><section id="method" class="section method"><p class="eyebrow">${t('COMPRENDRE & REPRODUIRE','UNDERSTAND & REPRODUCE')}</p><h2>${t('Un calcul exact. Un périmètre limité.','An exact calculation. A limited scope.')}</h2><div class="method-grid"><div><h3>${t('Ce que l’archive documente','What the archive documents')}</h3><p>${s.sources} ${t('sources avec adjacency','sources with adjacency')}, ${s.urls} URL ${t('distinctes, dont','in total, including')} ${s.destination_only} ${t('destinations seules. Leurs liens sortants sont inconnus, pas réputés absents.','destination-only URLs. Their outgoing links are unknown, not assumed absent.')}</p><p>${s.unique_relations} ${t('relations dirigées uniques, dont','unique directed relations, including')} ${s.self_links} ${t('liens vers soi-même conservés. Une boucle ne raccourcit aucun chemin BFS. Le total des URL ne représente pas des pages intégralement auditées.','self-links retained. A loop cannot shorten a BFS path. The URL total does not represent fully audited pages.')}</p><p>${t('L’archive du 9 septembre suit l’intervention du 15 août. La correction de liens du 21 septembre racontée dans l’article est une preuve distincte, absente de ce graphe historique.','The 9 September archive follows the 15 August intervention. The 21 September link correction described in the article is separate evidence, absent from this historical graph.')}</p></div><div><h3>${t('Ce que le moteur fait','What the engine does')}</h3><p>${t('Recherche en largeur dans un graphe dirigé non pondéré. Couples dédupliqués ; fragments retirés ; paramètres de requête conservés ; slash final retiré sauf à la racine. Aucune fusion par canonical ou par langue.','Breadth-first search in a directed, unweighted graph. Pairs deduplicated; fragments removed; query strings retained; trailing slash removed except at the origin root. No canonical or language-based merging.')}</p><p>${t('Le nombre exact utilise BigInt. Seuls les 50 premiers chemins dans l’ordre lexicographique des URL sont matérialisés. Départ = destination : 0 lien et 1 chemin ; absence de chemin : longueur indisponible, jamais zéro.','Exact counts use BigInt. Only the first 50 paths in URL lexicographic order are materialised. Start = destination: 0 links and 1 path; no path: length unavailable, never zero.')}</p></div></div><details><summary>${t('Références calculées, disponibles sans JavaScript','Calculated references, available without JavaScript')}</summary>${display.references.map((r,i)=>`<article class="reference"><h3>${i===0?'FR':'EN'} · ${esc(display.records[r.target].label)}</h3><p class="url">${esc(r.root)} → ${esc(r.target)}</p><p>${esc(summary(r,lang))}</p><ol>${r.paths[0].map(u=>`<li class="url">${esc(u)}</li>`).join('')}</ol><a href="originals/path-analysis.json">path-analysis.json</a> · <a href="originals/graph.json">graph.json</a></article>`).join('')}</details><details><summary>${t('Provenance, fichiers originaux et empreintes','Provenance, original files and hashes')}</summary><p>${t('Paquet public Edikka 1.1.0 sous CC BY 4.0. Les onze fichiers originaux ont été vérifiés octet par octet contre le manifeste.','Public Edikka package 1.1.0, CC BY 4.0. All eleven original files were checked byte for byte against the manifest.')}</p><p>graph.json · SHA-256 <code class="url">${display.provenance.graph_sha256}</code></p><p>${t('Import public','Public import')} : ${display.provenance.accessed_at}</p><ul>${['manifest.json','graph.json','pages.csv','links.csv','paths.csv','decisions.csv','decisions-blank.csv','data-dictionary.csv','README.md','license.txt','reproduce-paths.mjs','path-analysis.json'].map(f=>`<li><a href="originals/${f}">${f}</a></li>`).join('')}</ul><p><a href="data/display.json">${t('Données d’affichage dérivées et traçabilité','Derived display data and provenance')}</a></p><p>${t('pages.csv et links.csv sont des extraits documentaires. Seul graph.json alimente le calcul général. Les H1 observés sont signalés ; ailleurs, les libellés proviennent des URL.','pages.csv and links.csv are documentary excerpts. Only graph.json drives the general calculation. Observed H1s are identified; all other labels come from URLs.')}</p></details><details id="reproduce"><summary>${t('Rejouer localement avec le même moteur','Replay locally with the same engine')}</summary><p>${t('Node.js 22 ou ultérieur, aucune dépendance. Depuis un clone du dépôt :','Node.js 22 or later, no dependencies. From a repository clone:')}</p><pre>npm test\nnpm run build\nnode originals/reproduce-paths.mjs\nnode src/replay.mjs scenario.json</pre><p>${t('Le dernier argument est le JSON exporté par la démonstration. Le même moteur pur sert le navigateur, les tests et cette commande. La date de calcul ne remplace pas la date d’observation.','The last argument is the JSON exported by the demo. The same pure engine powers the browser, tests and this command. The calculation date does not replace the observation date.')}</p><a href="https://github.com/edikkaweb/seo-architecture-demo/blob/main/docs/REPRODUCTION.md">${t('Procédure complète de reproduction','Full reproduction procedure')}</a></details></section><p id="announcement" role="status" aria-live="polite" class="sr-only"></p></main><footer class="wrap footer"><div><a class="brand" href="https://www.edikka.com/">edikka<span>.</span></a><p>${t('Comprendre. Vérifier. Décider.','Understand. Verify. Decide.')}</p></div><nav aria-label="${t('Liens de retour','Return links')}"><a href="https://www.edikka.com/${lang==='en'?'en/library':'bibliotheque'}#instrument-architecture-seo-decision-matrix">${t('La matrice dans la bibliothèque','The matrix in the library')} ↗</a><a href="https://www.edikka.com/${lang==='en'?'en/insights/seo/seo-architecture-website':'insights/seo/architecture-seo-site'}">${t('Le guide Architecture SEO','The SEO Architecture guide')} ↗</a><a href="https://github.com/edikkaweb/seo-architecture-demo">${t('Code source & documentation','Source code & documentation')} ↗</a></nav><p class="small legal">${t('Données : Edikka, CC BY 4.0. Code de cette démonstration : MIT. Démo 1.0.0. Aucun traceur ajouté. Aucun résultat de trafic, d’indexation ou de classement n’est mesuré.','Data: Edikka, CC BY 4.0. Demo code: MIT. Demo 1.0.0. No added trackers. Traffic, indexation and rankings are not measured.')}</p></footer></body></html>`;}
